"""Config flow: ask for a scoped integration token, validate it, done.

Deliberately NOT an email/password login form -- see architecture doc
"Auth model". The token is generated by the user from the LazyPot
website/app account settings, not entered here from scratch.
"""

from __future__ import annotations

import logging
from collections.abc import Mapping
from typing import Any

import voluptuous as vol
from homeassistant.config_entries import ConfigFlow, ConfigFlowResult
from homeassistant.helpers.aiohttp_client import async_get_clientsession

from .api import LazyPotApiClient, LazyPotApiError, LazyPotAuthError, is_account_id
from .const import CONF_API_TOKEN, CONF_BASE_URL, DEFAULT_API_BASE_URL, DOMAIN

_LOGGER = logging.getLogger(__name__)

STEP_USER_SCHEMA = vol.Schema({vol.Required(CONF_API_TOKEN): str})


class LazyPotConfigFlow(ConfigFlow, domain=DOMAIN):
    """Handle a config flow for LazyPot."""

    VERSION = 1

    async def _async_get_account_id(
        self, api_token: str, base_url: str
    ) -> tuple[str | None, str | None]:
        """Validate a token. Return (account_id, None) or (None, error key)."""
        client = LazyPotApiClient(
            async_get_clientsession(self.hass),
            api_token=api_token,
            base_url=base_url,
        )
        try:
            return await client.async_get_account_id(), None
        except LazyPotAuthError:
            return None, "invalid_auth"
        except LazyPotApiError:
            return None, "cannot_connect"
        except Exception:  # noqa: BLE001 - last-resort guard, log + show generic error
            _LOGGER.exception("Unexpected error validating LazyPot token")
            return None, "unknown"

    async def async_step_user(
        self, user_input: dict[str, Any] | None = None
    ) -> ConfigFlowResult:
        errors: dict[str, str] = {}

        if user_input is not None:
            account_id, error = await self._async_get_account_id(
                user_input[CONF_API_TOKEN],
                user_input.get(CONF_BASE_URL, DEFAULT_API_BASE_URL),
            )
            if error:
                errors["base"] = error
            else:
                # One config entry per LazyPot account, not per device or
                # token -- the devices endpoint already returns the whole fleet.
                await self.async_set_unique_id(account_id)
                self._abort_if_unique_id_configured()
                return self.async_create_entry(title="LazyPot", data=user_input)

        return self.async_show_form(
            step_id="user", data_schema=STEP_USER_SCHEMA, errors=errors
        )

    async def async_step_reauth(
        self, entry_data: Mapping[str, Any]
    ) -> ConfigFlowResult:
        """Start reauth when the coordinator raises ConfigEntryAuthFailed."""
        return await self.async_step_reauth_confirm()

    async def async_step_reauth_confirm(
        self, user_input: dict[str, Any] | None = None
    ) -> ConfigFlowResult:
        """Ask for a new token, validate it and update the existing entry."""
        errors: dict[str, str] = {}
        reauth_entry = self._get_reauth_entry()

        if user_input is not None:
            account_id, error = await self._async_get_account_id(
                user_input[CONF_API_TOKEN],
                reauth_entry.data.get(CONF_BASE_URL, DEFAULT_API_BASE_URL),
            )
            if error:
                errors["base"] = error
            else:
                await self.async_set_unique_id(account_id)
                data_updates = {CONF_API_TOKEN: user_input[CONF_API_TOKEN]}
                if not is_account_id(reauth_entry.unique_id):
                    # Entry from before 1.0.2 (unique_id was a token prefix):
                    # there is nothing to compare against yet, so adopt the
                    # account id now, unless another entry already has it.
                    other = self.hass.config_entries.async_entry_for_domain_unique_id(
                        DOMAIN, account_id
                    )
                    if other is not None and other.entry_id != reauth_entry.entry_id:
                        return self.async_abort(reason="already_configured")
                    return self.async_update_reload_and_abort(
                        reauth_entry, unique_id=account_id, data_updates=data_updates
                    )
                # A token from a different LazyPot account must not silently
                # replace this entry's devices with someone else's.
                self._abort_if_unique_id_mismatch(reason="wrong_account")
                return self.async_update_reload_and_abort(
                    reauth_entry, data_updates=data_updates
                )

        return self.async_show_form(
            step_id="reauth_confirm",
            data_schema=STEP_USER_SCHEMA,
            errors=errors,
        )
